sql:
SELECT Country
FROM singer
WHERE Age > 40 AND Age < 30;

SELECT Year, AVG(Weight), AVG(Horsepower) AS Horsepower, AVG(Weight) AS Weight
FROM cars_data
GROUP BY Year;

SELECT Location, COUNT(*) AS Count
FROM shop
GROUP BY Location;

SELECT Document_ID, Template_ID, Document_Description
FROM Documents
WHERE Document_Name = 'Robbin CV';

SELECT Document_ID, Template_ID, Template_Type_Code
FROM Templates
ORDER BY Document_ID, Version_Number;

SELECT Paragraph_ID, Paragraph_Text
FROM Documents
WHERE Document_Name = 'Welcome to NY';

SELECT first_name, birth_date
FROM players
WHERE country_code = 'US';

SELECT ranking_date, COUNT(ranking_points) AS total_tours
FROM rankings
GROUP BY ranking_date;

SELECT year, COUNT(*) AS match_count
FROM matches
GROUP BY year;

SELECT name, result
FROM battle
WHERE bulgarian_commander != 'Boril';

SELECT Nationality, COUNT(*) AS Count
FROM people
GROUP BY Nationality;

SELECT name, COUNT(*) AS num_friends
FROM Highschooler
GROUP BY name;

SELECT name, age, weight
FROM Dogs
WHERE abandoned_yn = '1';

SELECT Citizenship, COUNT(*) AS Number_of_Singers
FROM singer
GROUP BY Citizenship;
